import React, { useState } from "react";

function Projects() {
  const [activeProject, setActiveProject] = useState(null);
  const [selectedImage, setSelectedImage] = useState(null);

  const projects = [
    {
      id: 1,
      title: "Credit Card Recommendation System",
      shortDescription:
        "A full-stack recommendation platform that helps users find the best credit card based on personal preferences and scoring logic.",
      description:
        "This project recommends credit cards using rule-based scoring, filtering, and data-based decision logic. It focuses on matching users with strong options based on their financial goals and preferences. It demonstrates backend logic, ranking systems, and practical full-stack development.",
      previewImage: "/CreditCardMain.png",
      video: "/CreditCardVideo.mp4",
      images: ["/CreditCardMain.png", "/CreditCardResults.png"],
      tech: ["React", "Java", "REST API", "Data Logic"],
    },
    {
      id: 2,
      title: "Tradernal",
      shortDescription:
        "A personalized trading journal with analytics, performance tracking, and AI-based coaching insights.",
      description:
        "Tradernal helps traders track their trades, review performance, and improve their consistency. It includes analytics, journaling features, and an AI-style coaching experience that gives users feedback and insights based on their activity.",
      previewImage: "/TradernalMain.png",
      video: "/TradernalVideo.mp4",
      images: ["/TradernalMain.png", "/TradernalDashboard.png"],
      tech: ["React", "Flask", "Python", "AI Features"],
    },
  ];

  const openProject = (project) => {
    setActiveProject(project);
  };

  const closeProject = () => {
    setActiveProject(null);
    setSelectedImage(null);
  };

  return (
    <section id="projects" className="projects-section">
      <div className="section-heading">
        <p className="section-label">Projects</p>
        <h2>Some of the work I’ve built</h2>
      </div>

      <div className="projects-grid">
        {projects.map((project) => (
          <div key={project.id} className="project-card">
            <img
              src={project.previewImage}
              alt={project.title}
              className="project-card-image"
            />

            <div className="project-card-content">
              <h3>{project.title}</h3>
              <p>{project.shortDescription}</p>

              <div className="tech-list">
                {project.tech.map((item, index) => (
                  <span key={index} className="tech-pill">{item}</span>
                ))}
              </div>

              <button
                className="project-btn"
                onClick={() => openProject(project)}
              >
                View Project
              </button>
            </div>
          </div>
        ))}
      </div>

      {activeProject && (
        <div className="modal-overlay" onClick={closeProject}>
          <div className="project-modal" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={closeProject}>×</button>

            <h3>{activeProject.title}</h3>
            <p className="modal-description">{activeProject.description}</p>

            <div className="modal-video-wrapper">
              <video src={activeProject.video} controls className="modal-video" />
            </div>

            <h4 className="gallery-title">Project Screenshots</h4>
            <div className="modal-gallery">
              {activeProject.images.map((image, index) => (
                <img
                  key={index}
                  src={image}
                  alt={`${activeProject.title} screenshot ${index + 1}`}
                  className="modal-gallery-image"
                  onClick={() => setSelectedImage(image)}
                />
              ))}
            </div>
          </div>
        </div>
      )}

      {selectedImage && (
        <div className="image-lightbox" onClick={() => setSelectedImage(null)}>
          <img src={selectedImage} alt="Selected project screenshot" className="lightbox-image" />
        </div>
      )}
    </section>
  );
}

export default Projects;
